#!/usr/bin/env node
/**
 * Generates 4 interview bank files with exactly 50 Q&A each.
 */
import { writeFile, mkdir } from "fs/promises";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT = join(__dirname, "..", "detailed", "interview-banks");

function bank(title, subtitle, pairs) {
  if (pairs.length !== 50) {
    throw new Error(`${title}: expected 50 questions, got ${pairs.length}`);
  }
  const body = pairs
    .map(
      ([q, a], i) =>
        `### Q${i + 1}: ${q}\n\n**Answer:** ${a}\n\n---`
    )
    .join("\n\n");
  return `# ${title}\n\n> ${subtitle}\n\n> **Target companies:** Google, Amazon, Flipkart, Uber, Microsoft, Meta.\n\n> **How to use:** Pick 2 questions daily. Read the question, answer aloud in 2–3 minutes, then check the full answer.\n\n---\n\n${body}\n`;
}

const banks = {
  "06-databases-interview-50.md": bank(
    "Databases Interview Q&A Bank — 50 Questions",
    "50 interview questions with full detailed answers for MongoDB, PostgreSQL, MySQL, Redis, Structured Query Language (SQL), transactions, and indexing.",
    [
      ["What is the difference between SQL and NoSQL databases?", "Structured Query Language (SQL) databases (PostgreSQL, MySQL) store data in fixed tables with rows and columns and enforce schema at write time. They excel at relationships using JOINs (combining tables) and full ACID (Atomicity, Consistency, Isolation, Durability) transactions. NoSQL (Not Only SQL) databases like MongoDB store flexible documents (often JSON-like Binary JSON called BSON) and scale horizontally more easily. SQL fits orders, payments, and reporting; NoSQL fits catalogs, logs, and rapidly changing schemas. Product companies often use both: one SQL database as the source of truth plus MongoDB or Redis for specific workloads."],
      ["Explain ACID properties with a money transfer example.", "Atomicity means all steps succeed or none do — debiting one account and crediting another must be one unit; a crash mid-transfer rolls back. Consistency means rules (like balance ≥ 0) always hold. Isolation means concurrent transfers do not see each other's half-finished work. Durability means once committed, data survives power loss (written to disk or replicated). Banks and e-commerce ledgers rely on ACID; interviewers at Flipkart or Amazon expect you to tie each letter to a real failure scenario."],
      ["What is the CAP theorem and how does it apply to MongoDB vs Redis?", "CAP (Consistency, Availability, Partition tolerance) states that during a network partition you can prioritize Consistency or Availability, not both. Partition tolerance is required in distributed systems because networks fail. MongoDB replica sets default to CP — they may refuse writes if a majority of nodes is unreachable to avoid stale data. Redis Cluster is often AP for reads — clients may get slightly stale values but the system stays up. Single-node PostgreSQL on one server is effectively CA until you add replication."],
      ["When would you choose PostgreSQL over MySQL?", "Choose PostgreSQL when you need advanced analytics (Common Table Expressions, window functions), rich types (JSONB, arrays, geographic information system extensions), strict standards compliance, or complex constraints. PostgreSQL handles concurrent writes and analytical queries well. Choose MySQL when the team standard is MySQL (common at Uber and Flipkart), you need simple high-read Online Transaction Processing (OLTP), or managed MySQL with Vitess sharding. Both are production-grade; know either for interviews."],
      ["When would you choose MongoDB over a SQL database?", "MongoDB fits when schema evolves frequently (startup product iterations), documents are read together (user profile with nested preferences), write volume is high and relationships are simple, or you need flexible nested arrays without heavy JOINs. Avoid MongoDB as the only store when you need complex multi-table reports, strict relational integrity across many entities, or heavy ad-hoc analytics with window functions — PostgreSQL wins there."],
      ["What is BSON and how does it differ from JSON?", "BSON (Binary JSON) is MongoDB's binary encoding of JSON-like documents. It supports additional types JSON lacks: Date, ObjectId (unique document identifier), Decimal128, and Binary data. BSON is faster to parse than text JSON and includes length prefixes for efficient traversal. In interviews, mention that drivers convert between JavaScript objects and BSON automatically — you still think in JSON shape at the application layer."],
      ["Explain embedding vs referencing in MongoDB schema design.", "Embedding stores related data inside one document (order with line items array). Use when data is always fetched together, size is bounded, and relationship is one-to-few. Referencing stores an identifier pointing to another collection (user document with order IDs or order with userId). Use when related data grows unbounded, is shared across documents, or needs independent queries. Over-embedding causes 16 MB document limit issues; over-referencing causes application-level JOINs similar to SQL."],
      ["How do MongoDB indexes work and what is the default _id index?", "MongoDB uses B-tree indexes (Balanced tree for range and equality lookups). Every collection automatically has a unique index on `_id`. Queries without a supporting index perform a collection scan (reading every document) — slow at scale. Create indexes on fields used in filter, sort, and lookup stages. Compound indexes follow the leftmost prefix rule: index on `{a:1,b:1}` helps queries on `a` alone or `a+b`, not `b` alone."],
      ["What is the MongoDB aggregation pipeline?", "The aggregation pipeline processes documents through stages like `$match` (filter), `$group` (aggregate), `$lookup` (join another collection), `$sort`, and `$project` (reshape fields). It is MongoDB's answer to SQL GROUP BY and JOIN for analytics. Example: count orders per user with `$match` on date range, `$group` by userId, `$sort` by count. Use `$explain` on aggregation to verify index usage — interviewers ask this for dashboard and reporting workloads."],
      ["Explain MongoDB replica sets and failover.", "A replica set is one primary node (accepts writes) and secondary nodes (replicate the oplog — operation log). If the primary dies, an election promotes a secondary. Clients should use a connection string with replica set name for automatic failover. Write concern `majority` ensures data is replicated before acknowledging — important for durability. Read concern `majority` avoids stale reads after failover. At Google-scale interviews, mention trade-off between durability and write latency."],
      ["What is MongoDB sharding?", "Sharding splits data across multiple shards (each often a replica set) using a shard key. The mongos router directs queries to the correct shard. A bad shard key (low cardinality or monotonic like timestamp-only) creates hot shards — one server gets all writes. Good keys distribute evenly (hashed userId). Sharding is for horizontal scale when a single replica set exceeds disk, memory, or write throughput limits."],
      ["What are the main SQL JOIN types?", "INNER JOIN returns rows where both tables match the join condition. LEFT (OUTER) JOIN keeps all rows from the left table and null-fills missing right matches — common for optional relations. RIGHT JOIN is the mirror. FULL OUTER JOIN keeps unmatched rows from both sides (PostgreSQL supports it; MySQL does not natively). CROSS JOIN is the Cartesian product — every row paired with every row. Interviews often ask you to write a query finding users with no orders — that is LEFT JOIN ... WHERE order.id IS NULL."],
      ["Explain database normalization (1NF, 2NF, 3NF) in plain language.", "First Normal Form (1NF): atomic columns, no repeating groups — no storing multiple phone numbers in one comma-separated field. Second Normal Form (2NF): no partial dependency on a composite key — every non-key column depends on the whole primary key. Third Normal Form (3NF): no transitive dependency — columns depend only on the primary key, not on other non-key columns. Normalization reduces redundancy and update anomalies. Denormalization is intentional duplication for read speed — know both."],
      ["When is denormalization acceptable?", "Denormalize when read performance dominates, joins are expensive at scale, and data is read far more than updated. Examples: storing `authorName` on each blog post to avoid joining users on every feed load, or embedding product snapshot on order line items so historical price stays correct. Trade-offs: larger storage, risk of stale copied fields, harder updates. Cache (Redis) is another form of controlled denormalization."],
      ["What is a B-tree index and why do databases use it?", "A B-tree is a balanced tree where each node holds many keys and children, keeping tree height low. It supports O(log n) lookups, range scans (`WHERE age BETWEEN 20 AND 30`), and ordered retrieval for ORDER BY. Most relational databases and MongoDB default to B-tree variants. Interview tip: equality and range queries on indexed columns avoid full table scans; string prefix searches can use indexes, but `LIKE '%suffix'` often cannot."],
      ["What is a compound index and the leftmost prefix rule?", "A compound index spans multiple columns, e.g. `(country, city, zip)`. The leftmost prefix rule means the index helps queries filtering on `country`, or `country+city`, or all three — but not `city` alone without `country`. Order matters: put high-selectivity or equality columns first, then range columns. Wrong column order wastes the index — a common senior interview question at Amazon."],
      ["What is a covering index?", "A covering index includes all columns the query needs, so the database reads only the index without touching the main table (index-only scan). Example: index on `(user_id, created_at)` for `SELECT created_at FROM orders WHERE user_id = ?` — if `created_at` is in the index, no heap lookup. Smaller result sets and less input/output make queries much faster. In PostgreSQL, use `INCLUDE` columns for this pattern."],
      ["What is a partial index?", "A partial index indexes only rows matching a condition, e.g. `WHERE deleted_at IS NULL`. Smaller index size, faster writes, faster lookups for the common case (active users only). PostgreSQL and MongoDB support partial indexes. Use when queries always filter the same subset — soft-deleted records, pending orders, or published posts only."],
      ["How do you use EXPLAIN to optimize a slow query?", "Run EXPLAIN or EXPLAIN ANALYZE (PostgreSQL/MySQL) to see the execution plan: sequential scan vs index scan, estimated rows, join order, and actual timings. Look for high cost nodes, nested loop joins on large tables without indexes, and sort operations on huge datasets. Fix by adding indexes, rewriting JOINs, limiting selected columns, or paginating. At Microsoft interviews, walk through one real slow query you fixed."],
      ["What is the N+1 query problem?", "N+1 happens when code loads N parent records (1 query) then runs one query per parent for related data (N queries) — e.g. load 100 posts, then 100 queries for each author's name. Total: 101 queries. Fix with JOIN, batch `WHERE author_id IN (...)`, ORM eager loading (Prisma `include`, Mongoose `populate`), or DataLoader pattern in GraphQL. This bug appears constantly in Node.js backends and is a favorite Flipkart question."],
      ["What is connection pooling and why does it matter?", "Opening a database connection is expensive (TCP handshake, authentication, memory on server). A pool maintains reusable connections; the app borrows and returns them. Without pooling, traffic spikes exhaust connections or add latency. Configure max pool size based on database limits — PostgreSQL default max_connections is often 100. Prisma and `pg` Pool handle this; watch for pool exhaustion under load tests."],
      ["Explain transaction isolation levels.", "Isolation levels control what concurrent transactions see. Read Uncommitted: dirty reads possible (rarely used). Read Committed: only committed data visible — PostgreSQL default. Repeatable Read: same row reads consistent within transaction — MySQL InnoDB default. Serializable: full isolation, may use locks and reduce concurrency. Higher isolation prevents anomalies (dirty read, non-repeatable read, phantom read) but increases lock contention. Pick the lowest level that keeps data correct."],
      ["What is a database deadlock and how do you prevent it?", "Deadlock occurs when transaction A locks row 1 waiting for row 2 while transaction B locks row 2 waiting for row 1 — neither can proceed. Databases detect and abort one transaction. Prevention: acquire locks in consistent order (always lock user then order), keep transactions short, use row-level locks wisely, avoid unnecessary `SELECT FOR UPDATE`. Retry aborted transactions with exponential backoff in application code."],
      ["Compare optimistic vs pessimistic locking.", "Pessimistic locking locks rows upfront (`SELECT FOR UPDATE`) — safe for high contention inventory (last ticket in concert). Optimistic locking uses a version column — read row with version 5, update only if still version 5; if someone else updated, retry. Optimistic fits low collision e-commerce carts; pessimistic fits financial debits. MongoDB uses atomic operators like `findOneAndUpdate` with conditions for optimistic patterns."],
      ["What are read replicas and what is replication lag?", "Read replicas copy data from the primary for read scaling. Writes go to primary; reads can go to replicas. Replication lag is delay before a write appears on replicas — milliseconds to seconds under load. Risk: user updates profile, immediately reads replica, sees old data. Mitigations: read-your-writes routing (same user to primary briefly), session stickiness, or accept eventual consistency for feeds. Uber and Netflix use replicas heavily."],
      ["Explain database sharding vs partitioning.", "Partitioning splits data within one database server (PostgreSQL table partitions by date range on one instance). Sharding splits across multiple servers (user IDs 1–1M on shard A, 1M+ on shard B). Partitioning simplifies archival (drop old partition); sharding scales beyond one machine's limits. Both require careful key choice to avoid hot spots. Vitess shards MySQL; MongoDB has native sharding."],
      ["What Redis data structures should you know for interviews?", "Strings (cache values, counters with INCR), Lists (queues with LPUSH/BRPOP), Sets (unique tags, mutual followers), Sorted Sets (leaderboards with score-based rank), Hashes (object fields like user session), Streams (event logs), HyperLogLog (approximate unique counts), Bitmap (daily active users). Redis is in-memory — sub-millisecond latency. Know which structure maps to which product feature."],
      ["Explain the cache-aside pattern.", "Application checks Redis first. On miss, read database, store in Redis with Time To Live (TTL), return to client. On write, update database then delete or update cache (cache invalidation). Most common caching pattern at product companies. Set TTL to balance freshness vs load — product catalog might be 5 minutes; user session might be 24 hours. Monitor hit rate; below 80% on hot keys suggests wrong keys or TTL."],
      ["What is write-through vs write-behind caching?", "Write-through: every write updates cache and database synchronously — strong consistency, higher write latency. Write-behind (write-back): write to cache first, async flush to database — faster writes, risk of data loss on crash. Read-through: cache layer loads from DB on miss automatically (client always talks to cache). Interview answer: use cache-aside for most REST APIs; write-through when stale cache is unacceptable."],
      ["How does Redis pub/sub work and when would you use it?", "Publishers send messages to channels; subscribers receive in real time. Fire-and-forget — no persistence if subscriber offline. Use for live notifications, chat fan-out, cache invalidation signals across app servers. For durable messaging use Redis Streams, Kafka, or RabbitMQ. At Meta-scale design questions, pub/sub is for ephemeral broadcast, not order processing."],
      ["What are Redis sorted sets used for?", "Sorted sets store unique members each with a numeric score, kept sorted. Commands: ZADD (add with score), ZRANK/ZREVRANK (position), ZRANGE (top N). Perfect for leaderboards, rate limiter sliding windows, priority task queues. Flipkart-style gamification and Uber driver dispatch scoring often map to sorted sets or similar rank structures."],
      ["Explain Redis TTL and eviction policies.", "TTL (Time To Live) expires keys automatically — `SET key value EX 3600`. When memory is full, eviction policies apply: `allkeys-lru` evicts least recently used keys globally; `volatile-lru` evicts only keys with TTL. Choose policy based on whether all keys are cache (allkeys) or mix of cache and required data. Monitor memory usage — Redis is fast until Out Of Memory (OOM) kills writes."],
      ["Compare Redis RDB snapshots vs AOF persistence.", "RDB: periodic point-in-time snapshots — compact, fast restart, may lose last few minutes of writes. AOF (Append Only File): logs every write — more durable, larger files, slower restart (can rewrite). Many teams use both or accept Redis as pure cache with rebuild-from-DB on restart. For session store durability, enable AOF with `everysec` fsync balance."],
      ["What is Prisma and how does it compare to raw SQL?", "Prisma is a TypeScript Object-Relational Mapper (ORM) generating a type-safe client from a schema file. It supports PostgreSQL, MySQL, SQLite, MongoDB. Benefits: autocomplete, compile-time errors, migrations. Raw SQL via `$queryRaw` for complex reports. Compared to raw SQL: less boilerplate, easier refactors; trade-off is abstraction leakage on very complex queries. Standard in modern MERN stacks."],
      ["What is Mongoose and what problems does it solve?", "Mongoose is the Object Document Mapper (ODM) for MongoDB in Node.js. It adds schema validation, defaults, middleware hooks (pre-save hashing passwords), virtuals, and population (join-like loading of references). Without Mongoose, you validate in application code only. Know `Schema`, `Model`, indexes in schema, and that strict mode strips unknown fields by default."],
      ["What are database migrations and best practices?", "Migrations are versioned schema changes (add column, create index) applied consistently across environments. Tools: Prisma Migrate, Flyway, Liquibase, Alembic. Best practices: never edit production manually; backward-compatible steps (add nullable column before backfill); deploy code that works with old and new schema; create indexes `CONCURRENTLY` on PostgreSQL to avoid locking. Failed migration rollback plan is a senior interview topic."],
      ["How would you schema-design an e-commerce order system?", "Users table (id, email). Products (id, sku, price — price snapshot on order line, not live product price). Orders (id, user_id, status, total). Order_items (order_id, product_id, quantity, unit_price at purchase). Payments separate with transaction id. Use foreign keys in SQL for integrity. Index `(user_id, created_at)` for order history. Redis cache product catalog; SQL for orders and payments with transactions."],
      ["What is polyglot persistence?", "Using multiple database types in one system for the right job: PostgreSQL for transactions, MongoDB for product catalog, Redis for sessions and cache, Elasticsearch for search. MERN apps often say MongoDB only, but Flipkart/Uber-scale systems mix stores. Interview: justify each choice with access pattern, consistency needs, and query shape — not buzzwords."],
      ["What is eventual consistency and when is it acceptable?", "Eventual consistency means replicas converge over time; reads may temporarily return old values. Acceptable for social feeds, view counts, recommendation scores, non-critical profile fields. Not acceptable for account balance, inventory deduction, or idempotent payment id without strong checks. Always state the business impact of stale data in interviews."],
      ["What is a primary key vs a unique index?", "Primary key uniquely identifies a row; only one per table; often clustered (physical row order follows it in MySQL InnoDB). Unique index enforces uniqueness on column(s) but allows multiple unique indexes and one NULL in SQL (unless NOT NULL). Use surrogate keys (auto-increment id, UUID) vs natural keys (email) — UUIDs ease distributed inserts; integers are smaller and faster to join."],
      ["What are foreign keys and should you always use them?", "Foreign keys enforce referential integrity — cannot insert order with invalid user_id. Cascades can DELETE user and related rows automatically. Benefits: database-enforced consistency. Drawbacks: complicates sharding, migrations, and high-write distributed systems — some teams enforce in application layer instead. For most MERN/SQL apps on one database, use foreign keys; at shard scale, discuss trade-offs openly."],
      ["What are SQL window functions? Give an example.", "Window functions compute across related rows without collapsing groups like GROUP BY. Example: `ROW_NUMBER() OVER (PARTITION BY department ORDER BY salary DESC)` ranks employees within each department. Others: `LAG`, `LEAD`, running totals. PostgreSQL excels here. Use for top-N per group, moving averages, and analytics dashboards — common Amazon data interview SQL question."],
      ["What are prepared statements and why use them?", "Prepared statements parse SQL once, execute many times with different parameters — faster and immune to SQL injection when used correctly (`$1` placeholders, never string concat). ORMs use them by default. Example attack without preparation: input `' OR '1'='1` breaks naive queries. Always parameterize user input — security and performance win."],
      ["How does MySQL InnoDB differ from MyISAM?", "InnoDB supports transactions, row-level locking, foreign keys, and crash recovery — default and required for production. MyISAM has table-level locks, no transactions — legacy, avoid. InnoDB stores rows in primary key order (clustered index). Interviewers at Indian product companies expect you to say InnoDB for any transactional workload."],
      ["What is PostgreSQL JSONB and when to use it?", "JSONB stores JSON in binary parsed form — indexable with GIN indexes, queryable with operators (`->`, `->>`, `@>`). Use for semi-structured attributes (user preferences, metadata) that change often without migrations. Not a replacement for normalized relations — avoid storing entire order graph in one JSON blob if you need relational queries. Hybrid model is common at startups scaling to Microsoft-level interviews."],
      ["Explain the difference between DELETE, TRUNCATE, and DROP.", "DELETE removes rows matching condition, row-by-row, can rollback in transaction, triggers fire. TRUNCATE removes all rows quickly by deallocating pages — faster, usually cannot rollback, resets auto-increment. DROP removes entire table structure and data. Production: prefer soft delete (`deleted_at`) for audit trails; TRUNCATE staging tables; never DROP without backups."],
      ["How do you handle pagination at scale — OFFSET vs cursor?", "OFFSET/LIMIT (`LIMIT 20 OFFSET 100000`) scans and skips 100k rows — slow on large tables. Cursor (keyset) pagination uses `WHERE id > last_seen_id ORDER BY id LIMIT 20` — constant time with index. Use cursor for infinite scroll feeds (Instagram, Flipkart product lists). OFFSET is fine for small admin pages."],
      ["How would you choose a database for a new startup MVP vs at scale?", "MVP: one managed PostgreSQL or MongoDB on Railway/Supabase/Atlas — minimize ops. Add Redis when read latency hurts. At scale: read replicas, connection pooling (PgBouncer), cache hot paths, consider sharding when vertical scale (bigger server) fails. Match database to team skills and query patterns. Interviewers want phased evolution, not premature Kafka plus 5 databases on day one."],
      ["What Redis command would you use for a rate limiter?", "Fixed window: INCR key, EXPIRE on first increment, reject if count > limit. Sliding window: sorted set ZADD with timestamp score, ZREMRANGEBYSCORE to drop old entries, ZCARD to count. Token bucket can be simulated with Lua script for atomicity. Return HTTP 429 Too Many Requests when exceeded — standard API design at Uber and public APIs."],
      ["Summarize how you would answer 'design the data layer for a ride-sharing app' in an interview.", "Users and drivers in SQL with geo indexes or PostGIS. Trips table with status state machine, transactional payment records. Redis for driver location cache and nearby driver queries (GEORADIUS). MongoDB optional for trip event logs. Read replicas for trip history. Strong consistency on payment; eventual on driver location. Mention partition by city at scale. Connect each store to a concrete access pattern — that is what L5 interviews reward."],
    ]
  ),

  "08b-dsa-ds-interview-50.md": bank(
    "DSA Data Structures Interview Q&A Bank — 50 Questions",
    "50 interview questions with full detailed answers for arrays, linked lists, stacks, queues, trees, heaps, graphs, and tries.",
    [
      ["What is an array and what are its core operations' time complexities?", "An array is a contiguous block of memory storing elements at indices 0 to n-1. Access by index is O(1) because address = base + index × element size. Search unsorted array is O(n). Insert or delete at end is O(1) amortized for dynamic arrays; at middle requires shifting — O(n). Arrays excel at random access and cache locality (CPU prefetch). Most interview problems start with arrays — master index arithmetic and bounds."],
      ["What is a dynamic array and how does resizing work?", "Dynamic arrays (JavaScript Array, Python list, Java ArrayList) grow when full — typically double capacity, copy elements to new block — amortized O(1) append. Occasional O(n) resize. Capacity vs length: allocated slots vs used slots. Interview tip: mention amortized analysis when asked why append is O(1). Pre-allocate when size known to avoid repeated copies."],
      ["When should you use an array vs a linked list?", "Use arrays for random access, sorting, binary search, two-pointer techniques, and when memory locality matters. Use linked lists when you need O(1) insert/delete at a known node (with pointer), no reallocation, or implementing LRU cache with hash map + doubly linked list. Arrays dominate in practice due to cache performance — linked lists win in specific structural problems, not general storage."],
      ["What is a singly linked list and how do you reverse it?", "Singly linked list nodes hold `value` and `next` pointer. Reverse iteratively: maintain `prev`, `curr`, `next`; set `curr.next = prev`, advance pointers — O(n) time, O(1) space. Recursive reverse: reverse rest of list, point next node back — O(n) space for call stack. Classic Amazon and Microsoft phone screen question. Always clarify if singly or doubly linked."],
      ["What is a doubly linked list and why use it?", "Doubly linked lists add `prev` pointer — traverse backward, delete node in O(1) if you have pointer to node (no need to find predecessor). Used in LRU cache (move to front on access), browser history, text editor cursors. Cost: extra memory per node and more pointer updates on insert. Interview: LRU Cache is the flagship doubly linked list + hash map problem."],
      ["How do you detect a cycle in a linked list?", "Floyd's tortoise and hare: slow pointer moves 1 step, fast 2 steps. If they meet, cycle exists. To find cycle start: reset slow to head, move both 1 step until they meet at entrance — O(n) time, O(1) space. Alternative: hash set of visited nodes — O(n) space. Explain why fast-slow works — distance modulo cycle length."],
      ["What is a stack and what are its operations?", "Stack is Last-In-First-Out (LIFO): push (add top), pop (remove top), peek (view top). All O(1) with array or linked list backend. Use for matching parentheses, undo operations, depth-first search (DFS) iterative, evaluating expressions, monotonic stack problems. JavaScript: use array with `push`/`pop` — do not use `shift` (O(n))."],
      ["What is a queue and what are its operations?", "Queue is First-In-First-Out (FIFO): enqueue (add rear), dequeue (remove front). O(1) with linked list or circular buffer. Use for breadth-first search (BFS), task scheduling, rate limiting buffers. JavaScript lacks efficient queue on array — use linked list or track head index. Circular queue reuses array slots with front/rear pointers modulo capacity."],
      ["What is a deque (double-ended queue)?", "Deque allows insert and delete at both front and rear in O(1). Implements queue, stack, or sliding window max (with monotonic deque). JavaScript has no built-in deque — simulate with doubly linked list or use `deque` in Python interviews. Sliding window maximum is the classic deque interview problem at Google."],
      ["How can you implement a queue using two stacks?", "Use stack `in` for enqueue (push), stack `out` for dequeue. On dequeue, if `out` empty, pop all from `in` pushing to `out`, then pop `out`. Amortized O(1) per operation. Demonstrates understanding of converting LIFO to FIFO. Follow-up: thread safety and Amortized analysis explanation."],
      ["What is a binary tree?", "Binary tree: each node has at most two children (left, right). Root has no parent. Leaf has no children. Height of node = edges to deepest leaf; depth = edges from root. Full binary tree: every node has 0 or 2 children. Complete binary tree: filled level by level left to right — basis for heap array storage. Binary trees underpin Binary Search Trees and heaps."],
      ["What is a Binary Search Tree (BST) and its complexity?", "BST property: left subtree values < node < right subtree values. Search, insert, delete average O(log n) when balanced; worst O(n) if skewed (sorted insert). In-order traversal yields sorted order. Self-balancing variants (AVL, Red-Black) guarantee O(log n). Always mention balance in interviews — unbalanced BST is a linked list in disguise."],
      ["Explain tree traversals: in-order, pre-order, post-order, level-order.", "In-order (left, node, right): sorted order for BST. Pre-order (node, left, right): copy tree, prefix expressions. Post-order (left, right, node): delete tree, postfix expressions. Level-order: BFS with queue, level by level — shortest path in unweighted tree. Know recursive and iterative versions. Flipkart often asks level-order zigzag variant."],
      ["What is the difference between height and depth of a tree?", "Depth of node = number of edges from root to node (root depth 0). Height of node = edges to farthest leaf below it. Tree height = root height. Balanced tree height ≈ log n. Skewed tree height = n-1. These definitions matter for recursion stack depth and O(log n) vs O(n) claims."],
      ["What is a heap and what is the heap property?", "Heap is complete binary tree with heap property: min-heap — parent ≤ children (root is minimum); max-heap — parent ≥ children. Stored as array: parent at i, children at 2i+1 and 2i+2. Insert and extract-min are O(log n) via bubble up/down. Use for priority queues, Top K elements, Dijkstra's algorithm, merge K sorted lists."],
      ["Compare min-heap vs max-heap use cases.", "Min-heap: get smallest element — Dijkstra, scheduling earliest deadline, kth smallest stream. Max-heap: get largest — Top K frequent, median from two heaps (max-heap lower half, min-heap upper half). JavaScript: implement manually or use library; Python `heapq` is min-heap only — negate values for max-heap."],
      ["What are heap insert and extract operations?", "Insert: append to end of array, bubble up comparing with parent until heap property restored — O(log n). Extract-min: swap root with last element, remove last, bubble down choosing smaller child — O(log n). Build heap from array in O(n) with bottom-up heapify — know this beats n insertions for initialization."],
      ["What is a priority queue and how is it implemented?", "Priority queue supports insert with priority and extract highest (or lowest) priority element. Binary heap gives O(log n) insert and extract. Used in task schedulers, event simulation, A* search. Unlike FIFO queue, order depends on priority not arrival time. Fibonacci heap improves Dijkstra theoretically but binary heap is standard in interviews."],
      ["How do you represent a graph?", "Adjacency list: array of lists — for each vertex, list neighbors. Space O(V+E), best for sparse graphs. Adjacency matrix: V×V boolean/weight matrix — O(1) edge lookup, O(V²) space, good for dense graphs. Edge list: list of pairs — simple for Kruskal's algorithm. State representation choice in every graph interview."],
      ["What is the difference between directed and undirected graphs?", "Undirected: edge A—B means travel both ways — friendships (mutual). Directed: edge A→B one way — Twitter follow, dependency graph. Degree: undirected counts both ends; directed splits in-degree and out-degree. Cycle detection differs — directed needs three-color DFS or topological sort; undirected uses Union-Find or DFS parent tracking."],
      ["What is a weighted graph?", "Edges carry weights (cost, distance, time). Shortest path uses Dijkstra (non-negative weights), Bellman-Ford (negative edges), Floyd-Warshall (all pairs small V). Unweighted shortest path uses BFS. Uber route and network latency problems map to weighted graphs — always clarify weights non-negative before saying Dijkstra."],
      ["When do you use adjacency list vs adjacency matrix?", "List: sparse graph (social network, road map) — memory efficient, iterate neighbors fast. Matrix: dense graph or need O(1) `isEdge(u,v)` — Floyd-Warshall, small V ≤ 500. For V=10⁶ and E=10⁷, matrix is impossible — list mandatory. Interview: ask V and E before picking."],
      ["What is a trie (prefix tree)?", "Trie stores strings character by character in tree nodes; each path from root spells a prefix. Search, insert, delete O(m) where m = word length. Shared prefixes save space vs storing full strings separately. Used for autocomplete, spell check, IP routing tables, word search on board. Each node map/array of 26 children for lowercase English."],
      ["What problems are tries especially good for?", "Prefix search: all words starting with 'app' — autocomplete. Exact match faster than hash for many short strings with shared prefixes. XOR maximum pair (bit trie). Less ideal when alphabet huge or strings very long with no shared prefixes — hash map may win. Google search suggestion is trie-class problem."],
      ["How does a hash map work internally?", "Hash function maps key to bucket index. Store key-value in bucket. Collisions: chaining (linked list per bucket) or open addressing (probe next slot). JavaScript Map maintains insertion order with O(1) average get/set. Load factor triggers resize and rehash. Worst case O(n) if all keys collide — mention in security context (hash flooding)."],
      ["What is collision resolution by chaining?", "Each bucket holds a list of entries whose keys hash to same index. Lookup: hash, traverse list comparing keys. Simple, handles load > 1 with linked lists. Java HashMap before Java 8 used chaining; now treeify long buckets. Average O(1) with good hash and load factor ~0.75."],
      ["What is a hash set and when to use it vs hash map?", "Hash set stores keys only — O(1) average contains check. Use for deduplication, cycle detection (visited set in BFS/DFS), two-sum complement lookup when you only need existence. Hash map when you need associated value (frequency count, index mapping). Both O(n) space trade for O(1) time."],
      ["What is Union-Find (Disjoint Set Union)?", "Union-Find tracks partitioned sets with `find(x)` (representative of x's set) and `union(x,y)` (merge sets). Path compression and union by rank give nearly O(1) amortized — inverse Ackermann. Use for Kruskal MST, connected components, dynamic connectivity, detecting cycle in undirected graph. Cleaner than DFS when only connectivity matters."],
      ["How would you design an LRU cache?", "Least Recently Used cache with O(1) get and put: hash map (key → node pointer) + doubly linked list (order by recency). On get: move node to head. On put: add to head, evict tail if over capacity. Capacity bounded memory. Classic Meta and Amazon Low-Level Design (LLD) question — know exact data structures and complexities."],
      ["What is a circular linked list?", "Last node points back to first instead of null. Used in round-robin scheduling, Josephus problem, buffer rings. Detect cycle variant: any node's next eventually returns. Breaking cycle carefully on delete. Sometimes used to simulate infinite list with fixed memory."],
      ["What is a skip list?", "Skip list: layered linked lists with express lanes — search O(log n) average probabilistically. Simpler to implement than balanced BST; used in Redis sorted set internals. Each node randomly promoted to upper levels. Alternative when red-black tree rotation logic is too heavy — mention conceptually in advanced interviews."],
      ["What is the difference between a B-tree and a binary search tree?", "B-tree nodes hold many keys and children — optimized for disk pages (database indexes). BST is binary in memory. B-tree height stays low for millions of keys — fewer disk reads. Interview link: MongoDB and PostgreSQL indexes use B-tree variants; in-memory algorithm problems use BST or hash."],
      ["How do you find in-order successor in a BST?", "If node has right subtree: successor is leftmost of right subtree. Else: walk up until current is left child — parent is successor. O(h) time. Used in BST delete when replacing with successor. Shows pointer manipulation understanding beyond textbook traversals."],
      ["What is level-order traversal and what data structure does it use?", "Level-order (BFS on tree): visit nodes row by row using a queue. Process node, enqueue left then right children. Used for printing levels, finding depth, serializing tree. Zigzag variant reverses every other level with deque or reverse slice. O(n) time, O(w) space where w = max width."],
      ["What is a complete vs full vs perfect binary tree?", "Full: every node 0 or 2 children. Complete: all levels filled except possibly last, filled left to right — heap requirement. Perfect: all internal nodes have 2 children, all leaves same depth — rare. Complete trees map cleanly to array heap indexing — know formulas for interview heap problems."],
      ["What is the degree of a vertex in a graph?", "Undirected: number of edges incident to vertex. Directed: in-degree (incoming edges), out-degree (outgoing). Handshaking lemma: sum of degrees = 2E in undirected graph. High-degree nodes (hubs) affect BFS queue size and algorithm choice — important in social graph questions."],
      ["Why do self-balancing trees exist?", "Plain BST degrades to linked list O(n) on sorted input. AVL trees keep height difference ≤ 1; Red-Black trees relax balance for fewer rotations on insert. Both guarantee O(log n) operations. Java TreeMap uses Red-Black. Interview: you rarely implement rotations but must know unbalanced BST is dangerous."],
      ["Explain cache locality and why arrays beat linked lists in practice.", "CPUs load memory in cache lines (~64 bytes). Array elements contiguous — prefetch hits cache. Linked list nodes scattered — pointer chasing causes cache misses. Same O(n) scan but arrays often 5–10× faster in real benchmarks. Mention when interviewer asks array vs linked list beyond Big-O."],
      ["How do you delete a node in a doubly linked list given a pointer?", "Update `prev.next = next` and `next.prev = prev`. Handle head and tail edge cases. O(1) time — why LRU uses doubly linked. Singly linked requires O(n) to find predecessor unless copying next node's data (hack, fails if next is null)."],
      ["What is a monotonic stack?", "Stack maintaining increasing or decreasing order. Pop smaller elements before push when finding next greater element. Used in daily temperatures, largest rectangle in histogram, stock span. Each element pushed and popped once — O(n) total. Pattern recognition question at Google."],
      ["What is a binary search tree delete case breakdown?", "Three cases: (1) leaf — remove. (2) one child — replace with child. (3) two children — replace value with in-order successor (or predecessor), delete successor. Case 3 preserves BST property. O(h) time. Practice all cases — interviewers love case 3."],
      ["How is a heap stored in an array?", "Index 0 = root. For node i: left child = 2i+1, right = 2i+2, parent = floor((i-1)/2). No pointers — cache friendly. Last non-leaf at index floor(n/2)-1. Heapify from there builds heap in O(n). Explain this mapping when implementing heap from scratch."],
      ["What is graph edge vs vertex count notation?", "V = vertices (nodes), E = edges. Sparse: E ≈ O(V). Dense: E ≈ O(V²). BFS/DFS time O(V+E). Space adjacency list O(V+E). Many graph problems state constraints — V ≤ 10⁵, E ≤ 10⁶ determines if O(V²) matrix fits in time limit."],
      ["What is a sentinel node (dummy head) in linked lists?", "Dummy node before real head simplifies insert/delete at head without special cases. `dummy.next = head`. Return `dummy.next` as new head after operations. Reduces off-by-one bugs in reverse, merge two sorted lists, remove nth from end. Standard interview technique — mention proactively."],
      ["Compare stack vs recursion for DFS.", "Recursion uses call stack implicitly — clean code, risk stack overflow on deep graphs (10⁵ depth). Iterative DFS uses explicit stack — control depth, can mark visited on stack. Tree DFS depth often safe; graph DFS on adjacency list may need iterative or increase stack limit. Tail recursion optimization limited in JavaScript."],
      ["What is a suffix tree vs trie?", "Trie stores prefixes from root forward. Suffix tree stores all suffixes of a string — powerful for substring search O(m) but complex to build. Suffix array + LCP is alternative. For interviews, trie suffices for autocomplete; mention suffix structures for advanced string matching (Google search index depth)."],
      ["How do you merge two sorted linked lists?", "Dummy head, pointer `curr`. Compare l1 and l2 heads, attach smaller, advance. O(n+m) time, O(1) space. Extension: merge K lists with min-heap — O(N log k). Microsoft favorite — tests pointer discipline without complex algorithms."],
      ["What is the Josephus problem and which structure helps?", "n people in circle, every k-th eliminated — find survivor. Simulated with circular linked list O(nk) or mathematical recurrence O(n). Shows creative use of circular structure. Occasional math-heavy interview variant — know brute force with queue or list."],
      ["Summarize time complexities for all major structures.", "Array access O(1), search O(n). Hash map average O(1) ops. Stack/queue O(1) push/pop. Linked list search O(n), insert at known node O(1). Balanced BST O(log n) search/insert. Heap O(log n) insert/extract. Trie O(m) per string length m. Graph BFS/DFS O(V+E). Recite this table fluently — baseline for every DSA round."],
      ["What is the most common mistake candidates make with linked lists?", "Losing reference to head, not handling null next, creating cycles accidentally, or using `array.shift()` thinking it is O(1). Always draw pointers, use dummy head, check `while (curr !== null)` vs `while (curr.next !== null)` depending on operation. Test empty list and single node — interviewers always include these edge cases."],
    ]
  ),

  "08-dsa-patterns-interview-50.md": bank(
    "DSA Patterns Interview Q&A Bank — 50 Questions",
    "50 interview questions with full detailed answers for two pointers, sliding window, hash map, binary search, Breadth-First Search (BFS), Depth-First Search (DFS), and dynamic programming intro.",
    [
      ["What is the two pointers pattern and when do you use it?", "Two pointers use index `left` and `right` (or slow/fast) scanning array or string from different positions. Use on sorted arrays for pair sums, palindrome check, removing duplicates in-place, merging sorted arrays, and container with most water. Often O(n) time O(1) space vs O(n²) brute force. First check if sorting or sorted input enables two pointers."],
      ["How does two pointers work on a sorted array for pair sum?", "Set left=0, right=n-1. If sum too small, left++; if too big, right--; if equal, record and move. O(n) after O(n log n) sort, or O(n) if already sorted. Works for 'two sum' in sorted array; unsorted version uses hash map. State why moving pointers is safe — monotonic reason."],
      ["What is the sliding window pattern?", "Sliding window maintains a contiguous subarray/substring window with `left` and `right` expanding or shrinking while tracking window state (sum, frequency map, distinct count). Fixed window: size k slides. Variable window: expand until invalid, then shrink from left. O(n) each element enters and leaves once. Classic for max sum subarray of size k, longest substring without repeating characters."],
      ["What is the difference between fixed and variable sliding window?", "Fixed: window size k constant — compute first window, slide by add right remove left. Variable: grow right until constraint violated (sum > target, duplicate char), then shrink left until valid again, track best answer at each valid state. Minimum window substring is variable window hard problem — Amazon favorite."],
      ["How does hash map pattern solve Two Sum?", "One pass: for each `nums[i]`, check if `target - nums[i]` exists in map; if yes return indices; else store `nums[i] → i`. O(n) time O(n) space. Template for complement lookup, anagram grouping, frequency counting. Explain trade: O(n) space buys O(1) lookup vs sorting O(n log n) space O(1)."],
      ["When do you use hash map for frequency counting?", "Count character or element frequencies: anagram detection, top K frequent, find duplicate, ransom note. Pattern: `map.set(c, (map.get(c)||0)+1)`. Compare maps or use single map with decrement for anagram. O(n) time. Follow-up: array size n, values 1..n — use array as hash O(1) space (pigeonhole)."],
      ["Explain binary search beyond sorted arrays.", "Binary search works on monotonic predicate: find first/last true in `[false,...,false,true,...,true]`. Examples: minimum capacity to ship packages, square root, search rotated sorted array (modified compare). Template: `while (lo < hi) { mid = lo + (hi-lo)/2; if (ok(mid)) hi = mid; else lo = mid+1; }`. O(log n) — always mention overflow-safe mid."],
      ["What is 'binary search on answer'?", "When answer is in range [lo, hi] and if value x works then all x' > x work (monotonic), binary search the answer space without explicit array. Check feasibility with helper `can(x)`. Used in Koko eating bananas, split array largest sum. Interview script: define monotonic property before coding."],
      ["What is the BFS (Breadth-First Search) template?", "Use queue. Enqueue start, mark visited. While queue: dequeue node, process, enqueue unvisited neighbors. Level-order: track queue size each iteration. Shortest path in unweighted graph — first time reaching target is minimum steps. O(V+E) time. Never forget visited set or infinite loop on cycles."],
      ["What is the DFS (Depth-First Search) template?", "Recursive: base case, mark visited, recurse neighbors. Iterative: stack push start. Use for exploring all paths, cycle detection, topological sort, connected components, island counting. O(V+E). Backtracking is DFS with undo (remove from path after explore). Depth limit for large graphs to avoid stack overflow."],
      ["When do you choose BFS vs DFS?", "BFS: shortest path unweighted, level-by-level, nearest layer (word ladder). DFS: enumerate paths, detect cycle with recursion stack colors, topological order, maze with one path. Memory: BFS O(width) queue; DFS O(depth) stack. Grid problems: both work for islands — BFS if shortest steps matter."],
      ["What is dynamic programming (DP) and when is it applicable?", "DP solves problems with optimal substructure and overlapping subproblems by storing subproblem results. Applicable when brute force recursion revisits same states — Fibonacci, knapsack, longest increasing subsequence. Steps: define state, recurrence, base case, iteration order, space optimization. Say 'DP' only after identifying overlapping subproblems."],
      ["What is the difference between memoization and tabulation?", "Memoization: top-down recursion + cache (hash map or array) — compute on demand. Tabulation: bottom-up fill table in known order — often no recursion stack. Same complexity usually. Tabulation easier to optimize space (rolling array). Interviews: start with memoization if recurrence natural, refactor to tabulation."],
      ["How do you define DP state in an interview?", "State = parameters fully describing subproblem — e.g. `dp[i]` = best answer using first i items, `dp[i][w]` = max value with weight limit w. Wrong state = wrong solution. Write recurrence in words before code: `dp[i] = max(dp[i-1], nums[i] + dp[i-2])`. Validate with small example manually."],
      ["Explain the Kadane's algorithm pattern.", "Maximum subarray sum: `currMax = max(nums[i], currMax + nums[i])`, track global max. O(n) O(1). DP view: dp[i] = max ending at i. Variants: return indices, circular array, max product (track min and max). Google easy-medium staple — know derivation not just memorization."],
      ["How does coin change DP work?", "Minimum coins for amount: `dp[0]=0`, `dp[a] = min(dp[a-coin]+1)` for each coin. Unbounded knapsack order — iterate amounts outer loop. Count ways: `dp[a] += dp[a-coin]`. O(amount × coins). Clarify unlimited vs 0/1 coin supply — changes inner loop direction."],
      ["What is the longest increasing subsequence (LIS) pattern?", "O(n²) DP: `dp[i]` = LIS ending at i. O(n log n) with patience sorting — binary search on tails array. Patience sorting is advanced but impresses at Microsoft. Return length vs actual sequence differs — sequence needs parent pointers."],
      ["How do you solve grid BFS problems like rotten oranges?", "Multi-source BFS: enqueue all sources (rotten oranges) with distance 0 simultaneously. Process level by level incrementing time. Shortest time for all cells. Template extends to 01 BFS (deque), fire spread, nearest gate. Mark visited when enqueue not dequeue to avoid duplicates."],
      ["What is topological sort and when is it needed?", "Linear ordering of DAG (Directed Acyclic Graph) where every edge u→v has u before v. Kahn's algorithm: BFS with in-degree zero queue. Or DFS post-order reverse. Use for course schedule, build order, dependency resolution. Cycle detection: if processed count < V, cycle exists — Flipkart dependency question."],
      ["What is backtracking and how differs from DP?", "Backtracking explores all choices with undo — subsets, permutations, N-queens, sudoku. Exponential time often. Prune invalid branches early. DP when subproblems repeat and optimal structure; backtracking when count/enumerate all solutions. Combination sum with reuse may use backtracking; with optimization and overlap → DP."],
      ["Explain the subsets generation pattern.", "For each element: include or exclude — recursion `backtrack(i, path)`. Or iterative bitmask 0 to 2^n-1. O(2^n) output size unavoidable. Subsets II adds sort + skip duplicates at same level. Communicate time dominated by output size."],
      ["How do permutations differ from subsets in approach?", "Permutations: use used array or swap, choose unused elements — n! leaves. Subsets: ordered by index, no reuse of earlier index in same path. Next permutation (lexicographic) uses two-pointer swap algorithm — occasional follow-up."],
      ["What is the merge intervals pattern?", "Sort by start time. Iterate: if current overlaps last merged (start ≤ last.end), extend last.end; else push new interval. O(n log n). Used for meeting rooms, insert interval, employee free time. Overlap condition critical — clarify inclusive vs exclusive endpoints."],
      ["What is the fast and slow pointers pattern beyond linked lists?", "Also tortoise-hare on arrays (find duplicate in O(1) space — Floyd cycle in index array), middle of linked list, palindrome linked list (find mid, reverse second half). O(n) one pass. Name pattern when interviewer sees two pointers moving at different speeds."],
      ["What is prefix sum and when to use it?", "Prefix[i] = sum of nums[0..i-1]. Range sum query O(1): prefix[j+1]-prefix[i]. 2D prefix for matrix region sum. Combine with hash map for subarray sum equals K — store prefix frequencies. O(n) preprocessing, O(1) or O(n) queries depending variant."],
      ["When is greedy algorithm correct and how to justify?", "Greedy picks locally optimal if problem has greedy choice property and optimal substructure — activity selection, non-overlapping intervals, Huffman coding. Prove or cite exchange argument. Wrong greedy on coin change {1,3,4} target 6 — greedy 4+1+1=3 coins, optimal 3+3=2. Always test counterexample mentally."],
      ["How do you binary search a rotated sorted array?", "Modified compare: if `nums[lo] <= nums[mid]` left half sorted, else right sorted. Check if target in sorted half, adjust lo/hi. O(log n). Duplicate values need `while (nums[hi]===nums[lo]) hi--` worst O(n). Amazon rotation search is standard."],
      ["What is tree DP intro — example house robber III?", "DP on tree: post-order compute `rob(node)` and `notRob(node)` from children returns. Cannot rob adjacent nodes. O(n). Pattern: recurse children, combine at parent. Also diameter of tree, max path sum — state often includes/excludes current node."],
      ["How do you detect cycle in directed graph?", "Three-color DFS: white unvisited, gray in current stack, black finished. Edge to gray node = cycle. Or Kahn topological sort — no complete order means cycle. Undirected: DFS track parent or Union-Find. State which graph type before answering."],
      ["Explain Dijkstra's algorithm at intro level.", "Shortest path from source in weighted graph with non-negative edges. Min-heap stores (distance, node). Relax neighbors if shorter path found. O((V+E) log V). Cannot handle negative edges — use Bellman-Ford. Uber ETA maps to Dijkstra on road network — mention non-negative distances."],
      ["When do you use Union-Find in patterns?", "Dynamic connectivity, count connected components after adding edges, Kruskal MST edge sorting + union, detect cycle in undirected graph on edge insert. Simpler than DFS when only group membership matters. O(α(n)) nearly constant per operation."],
      ["What is the meeting rooms II pattern?", "Min heap of end times: sort meetings by start, if start >= heap.min pop finished room, push end. Heap size = rooms needed. Greedy + heap. Variation of interval partitioning — classic calendar scheduling at Meta."],
      ["How does valid parentheses use stack pattern?", "Push opening brackets. On closing, pop must match. O(n). Extensions: generate valid strings, longest valid substring (stack stores indices), minimum remove to valid. Monotonic stack variant for nested depth."],
      ["Explain longest substring without repeating characters.", "Variable window + Set or Map of last index. Expand right, shrink left while duplicate. O(n). Map last index allows jump left directly — optimization. Template for many 'substring with constraint' problems."],
      ["How do you approach 3Sum pattern?", "Sort array. Fix i, two pointers on remainder for -nums[i]. Skip duplicates on i and pointers. O(n²). Extension 3Sum closest, 4Sum add another loop or hash. Communicate duplicate skipping to avoid double counting."],
      ["What is container with most water teaching?", "Two pointers at ends. Move shorter line inward — only shorter limits height, moving taller cannot increase area. O(n) greedy proof. Teaches monotonic pointer movement justification — interviewers want proof sketch."],
      ["What is binary tree level order traversal pattern?", "BFS queue, track size per level. Variants: zigzag, right side view (last per level), vertical order (column + BFS). O(n). Foundation for many tree problems before recursion-heavy ones."],
      ["How do you solve number of islands?", "Grid DFS or BFS: for each '1' not visited, increment count, flood fill mark visited. O(rows×cols). Union-Find alternative. Discuss in-place marking vs visited matrix — trade memory."],
      ["Explain climbing stairs as DP intro.", "dp[i] = ways to reach step i = dp[i-1] + dp[i-2]. Fibonacci. O(n) time O(1) space with two variables. Introduces transition from recursion to DP. Generalizes with steps 1 or 2 or custom step sizes."],
      ["What is house robber linear DP?", "Cannot rob adjacent houses: `dp[i] = max(dp[i-1], nums[i]+dp[i-2])`. O(n) O(1). Circular variant needs split into two linear runs excluding first or last house. Classic state machine DP intro."],
      ["How does word break use DP?", "`dp[i]` = can segment s[0..i)? Check j < i where `dp[j]` and s[j..i) in dictionary. O(n² × dict lookup). BFS also works. Trie speeds dictionary lookup. Google medium — define boolean DP clearly."],
      ["How should you communicate approach in a coding interview?", "Repeat problem, clarify inputs/outputs/edge cases, give brute force complexity, propose optimized pattern with why, get buy-in, code cleanly, test with example including edge case, state time/space. At Amazon use Leadership Principles tie-in sparingly. Silence while thinking is OK — narrate key insights."],
      ["How do you analyze time complexity for nested loops with two pointers?", "Single loop with two pointers moving total n steps — O(n) not O(n²). Sliding window each element enters and leaves once — O(n). Nested binary searches O(n log n). State invariant maintaining why pointers only move forward."],
      ["What is space optimization in DP — rolling array?", "If dp[i] depends only on dp[i-1] and dp[i-2], keep two variables not full array — O(1) space. 2D knapsack optimize to 1D array iterating weight backwards for 0/1 knapsack. Mention after correct 2D solution — shows senior polish."],
      ["When might bit manipulation appear with patterns?", "XOR cancels duplicates — single number. Count bits, subset generation with bitmask. Usually secondary to main patterns but quick wins on easy Google questions. Know `x & (x-1)` removes lowest set bit."],
      ["Why sort as preprocessing step?", "Enables two pointers, merge intervals, greedy scheduling, binary search on paired values. O(n log n) sort cost often dominates — still beats O(n²). Ask if sorting allowed or if original order must preserve."],
      ["Recursion vs iteration — interview preference?", "Either works if correct. Iteration avoids stack overflow. Recursion clearer for trees and backtracking. Mention converting recursion to stack if depth large. Tail recursion not optimized in JavaScript."],
      ["How do you pick a pattern when stuck?", "Ask: sorted? → two pointers/binary search. Subarray/substring contiguous constraint? → sliding window. Need counts or complements? → hash map. Tree/graph? → BFS/DFS. Optimal substructure? → DP. Try brute force then optimize — pattern emerges from bottleneck."],
      ["What are common DSA interview mistakes?", "Wrong complexity claim, missing empty input, off-by-one in binary search, not handling duplicates, infinite loop in while without progress, modifying array while iterating, forgetting visited in graph. Always walk through tiny example before coding."],
      ["Give a 60-second pattern cheat sheet for product company screens.", "Two pointers: sorted pairs/in-place. Sliding window: contiguous subarray max/min. Hash map: frequency, complement, index. Binary search: sorted or monotonic answer. BFS: shortest steps. DFS: explore paths, cycles, components. DP: max/min/count ways with overlapping subproblems. State pattern name, complexity, and one example problem — interviewers score recognition speed at Google and Flipkart."],
    ]
  ),

  "10b-networking-interview-50.md": bank(
    "Networking & HTTP Interview Q&A Bank — 50 Questions",
    "50 interview questions with full detailed answers for HTTP (Hypertext Transfer Protocol), HTTPS (HTTP Secure), TCP (Transmission Control Protocol), DNS (Domain Name System), CORS (Cross-Origin Resource Sharing), WebSockets, and REST (Representational State Transfer).",
    [
      ["What happens when you type a URL in the browser and press Enter?", "Browser parses URL (protocol, host, path). DNS (Domain Name System) resolves domain to Internet Protocol (IP) address. TCP (Transmission Control Protocol) connection to server port 443 for HTTPS or 80 for HTTP. TLS (Transport Layer Security) handshake if HTTPS. Browser sends HTTP GET request. Server responds; browser parses HTML, requests CSS/JS/images (more HTTP requests). JavaScript may call APIs. Rendering engine builds DOM and displays page. Interviewers want this chain — not just 'server sends page'."],
      ["Describe the structure of an HTTP request.", "Request line: method, path, HTTP version (`GET /api/users HTTP/1.1`). Headers: Host, Authorization, Content-Type, Accept, Cookie — key-value metadata. Blank line. Optional body (POST/PUT/PATCH) — often JSON. Each part has meaning for caches, auth, and content negotiation. Know mandatory Host header in HTTP/1.1."],
      ["Explain HTTP methods GET, POST, PUT, PATCH, DELETE.", "GET: read resource, safe (no server state change intended), idempotent, no body. POST: create or action, not idempotent — repeat may create duplicates. PUT: replace entire resource, idempotent. PATCH: partial update. DELETE: remove, idempotent. Safe methods only read; idempotent repeats same effect. REST design uses these semantics correctly — wrong verb is common junior mistake."],
      ["What does idempotent and safe mean for HTTP methods?", "Safe: client does not request server state change (GET, HEAD, OPTIONS) — still may log. Idempotent: multiple identical requests same effect as one (GET, PUT, DELETE) — important for retries after network timeout. POST is not idempotent — use idempotency keys for payments at Stripe/Uber scale."],
      ["Which HTTP status codes must you know for interviews?", "2xx success: 200 OK, 201 Created, 204 No Content. 3xx redirect: 301 permanent, 302 temporary, 304 Not Modified (cache). 4xx client: 400 Bad Request, 401 Unauthorized (not authenticated), 403 Forbidden (no permission), 404 Not Found, 409 Conflict, 429 Too Many Requests. 5xx server: 500 Internal Server Error, 502 Bad Gateway (upstream down), 503 Service Unavailable. Pick correct code in API design questions."],
      ["What important HTTP headers should you know?", "Request: Authorization (Bearer token), Content-Type, Accept, Cookie, User-Agent. Response: Content-Type, Set-Cookie, Cache-Control, ETag, Location (redirect). CORS: Access-Control-Allow-Origin. Security: Strict-Transport-Security. Headers drive caching, auth, and cross-origin behavior — senior engineers debug production issues via headers in browser DevTools."],
      ["What is HTTPS and why is it required?", "HTTPS is HTTP over TLS — encrypts data in transit, prevents eavesdropping and tampering, verifies server identity via certificates. Browsers mark HTTP sites insecure. Required for secure cookies, Service Workers, many APIs. Production APIs at Google, Amazon, Flipkart always HTTPS. Never send passwords over plain HTTP."],
      ["Walk through the TLS handshake at a high level.", "Client sends ClientHello (supported TLS versions, ciphers). Server sends certificate (public key signed by Certificate Authority). Client verifies certificate chain against trusted roots. Key exchange establishes symmetric session key. Remaining traffic encrypted with AES-GCM etc. TLS 1.3 reduces round trips vs 1.2. Mention certificate pinning in mobile apps as extra security."],
      ["Compare TCP vs UDP.", "TCP: connection-oriented, reliable, ordered delivery, congestion control — HTTP, HTTPS, WebSockets use TCP. UDP: connectionless, no guarantee of delivery or order, lower latency — video streaming, DNS queries, online games. Choose TCP when correctness matters; UDP when speed beats occasional loss. QUIC (HTTP/3) uses UDP with reliability built in."],
      ["Explain the TCP three-way handshake.", "SYN: client proposes sequence number. SYN-ACK: server acknowledges and sends its sequence. ACK: client acknowledges — connection established. Four-way teardown with FIN/ACK for graceful close. Understand for 'why first request is slow' (connection setup) and TIME_WAIT state. Load balancers terminate TCP and may reuse connections."],
      ["How does TCP ensure reliability?", "Sequence numbers, acknowledgments, retransmission on timeout or duplicate ACK, checksums, flow control (receiver window), congestion control (slow start, congestion avoidance). Duplicate packets discarded; order restored. Trade latency for reliability vs UDP. Interview link: HTTP assumes reliable stream — lost packets handled transparently by TCP."],
      ["How does DNS resolution work?", "Resolver checks cache → OS cache → recursive resolver (ISP or 8.8.8.8). Recursive queries root → TLD (.com) → authoritative nameserver for domain → returns A record (IPv4) or AAAA (IPv6). TTL (Time To Live) controls cache duration. CNAME aliases one name to another. Critical for CDN routing and failover — wrong DNS breaks entire service."],
      ["What are common DNS record types?", "A: domain to IPv4. AAAA: IPv6. CNAME: alias to another hostname. MX: mail server. TXT: verification, SPF (Sender Policy Framework). NS: nameserver delegation. CAA: which Certificate Authorities can issue certs. Interview: changing A record points domain to new server IP; CNAME cannot be at apex on some providers."],
      ["What is CORS and why does it exist?", "Cross-Origin Resource Sharing controls whether browser JavaScript on origin A (https://app.com) can read responses from origin B (https://api.com). Same-origin policy blocks by default for security. Server must send `Access-Control-Allow-Origin` (specific origin or careful wildcard without credentials). Without CORS header, browser blocks frontend from reading response even if server returned 200."],
      ["What is a CORS preflight request?", "For non-simple requests (custom headers like Authorization, Content-Type application/json on POST, PUT, DELETE), browser sends OPTIONS preflight first. Server responds with Allow-Origin, Allow-Methods, Allow-Headers, Max-Age. Actual request follows if allowed. Simple GET without custom headers may skip preflight. Fix backend OPTIONS handler — common MERN interview bug."],
      ["What are WebSockets and when use them?", "WebSocket upgrades HTTP connection to full-duplex persistent channel — both sides send anytime without new request per message. Use for chat, live scores, collaborative editing, real-time notifications. Lower overhead than polling. Not REST — different protocol after upgrade handshake. Slack, WhatsApp Web use WebSockets or similar."],
      ["Compare WebSockets vs HTTP long polling vs Server-Sent Events.", "Long polling: client repeats hanging GET — simple but high latency and overhead. Server-Sent Events (SSE): server pushes over single HTTP stream, one direction — good for live feeds. WebSockets: bidirectional, lowest latency for chat games. Choose based on directionality and infrastructure — SSE works through some proxies WebSockets struggle with."],
      ["What are REST principles?", "Representational State Transfer: stateless server, resources identified by URLs (`/users/123`), standard HTTP methods, representations (JSON/XML), hypermedia optional (HATEOAS). Layered system, cacheable responses. Not a protocol — architectural style. Contrast with GraphQL single endpoint and gRPC binary Remote Procedure Call."],
      ["REST vs GraphQL — trade-offs?", "REST: multiple endpoints, simple caching by URL, standard HTTP semantics, over-fetching if endpoints coarse. GraphQL: client specifies fields in one query, reduces round trips, strong typing with schema — harder caching, complexity at scale (N+1 with DataLoader). Netflix and Shopify use GraphQL internally; public APIs often REST for simplicity."],
      ["What is HTTP/1.1 vs HTTP/2?", "HTTP/1.1: text headers, one request per connection historically (keep-alive fixes), head-of-line blocking. HTTP/2: binary framing, multiplex many streams on one TCP connection, header compression (HPACK), server push (rarely used). Faster page loads. HTTP/2 still runs on TCP — TCP loss blocks all streams."],
      ["What is HTTP/3 and QUIC?", "HTTP/3 uses QUIC over UDP — independent streams avoid TCP head-of-line blocking, faster handshake with combined crypto, connection migration when IP changes (mobile). Google Chrome and Cloudflare widely support. Mention when discussing cutting-edge performance at Google interviews."],
      ["Cookies vs tokens — how do sessions work?", "Cookie: server Set-Cookie, browser auto-sends on domain — session id stored server-side or signed in cookie. Token (JSON Web Token JWT): stateless signed payload in Authorization header — no server session store, harder to revoke. HttpOnly cookie prevents JavaScript theft (Cross-Site Scripting). Secure flag HTTPS only. SameSite reduces Cross-Site Request Forgery."],
      ["What is the difference between 401 and 403?", "401 Unauthorized: authentication missing or invalid — client should login or refresh token. 403 Forbidden: authenticated but not allowed — wrong role or permission. Wrong status confuses clients — return 401 with WWW-Authenticate header for auth failures; 403 when user known but blocked."],
      ["What is a CDN (Content Delivery Network)?", "CDN caches static assets (images, JS, CSS, video) at edge PoPs (Points of Presence) near users — lower latency, less origin load. DNS or URL routing sends user to nearest edge. Cache invalidation on deploy. CloudFront, Cloudflare, Akamai. Essential for global products — Flipkart and Meta serve static content from edge."],
      ["Load balancer Layer 4 vs Layer 7?", "Layer 4 (Transport): routes by IP and port — fast, no HTTP parsing. Layer 7 (Application): routes by URL path, headers, cookies — sticky sessions, A/B tests. AWS Application Load Balancer is L7; Network Load Balancer is L4. TLS termination often at load balancer."],
      ["What is HTTP keep-alive?", "Persistent connection reuses TCP for multiple HTTP requests — avoids repeated handshakes. Default HTTP/1.1. Set Connection: keep-alive or rely on defaults. Connection pooling in clients (fetch with agent, axios) improves API client performance. Close when idle timeout exceeded."],
      ["What is chunked transfer encoding?", "Body sent in chunks without prior Content-Length — streaming large responses or dynamic generation. Header `Transfer-Encoding: chunked`. Each chunk size in hex followed by data. Ends with zero chunk. Useful for progressive rendering and Server-Sent Events."],
      ["What is content negotiation?", "Client Accept header lists preferred MIME types (`application/json`, `text/html`). Server picks best match or 406 Not Acceptable. Accept-Language for locale. API versioning sometimes via Accept header or URL `/v2/`. REST APIs usually fix JSON Content-Type."],
      ["How does ETag caching work?", "Server sends ETag (entity tag hash/version) with response. Client sends If-None-Match: etag on next request. If unchanged, server returns 304 Not Modified with empty body — saves bandwidth. Strong vs weak ETags. Used with Cache-Control for efficient API and static asset caching."],
      ["Explain Cache-Control directives.", "max-age=3600: fresh for 3600 seconds. no-cache: must revalidate with server before use. no-store: do not store at all (sensitive data). private vs public (CDN can cache public). stale-while-revalidate: serve stale while fetching new. Critical for performance and avoiding outdated UI — wrong caching causes bizarre production bugs."],
      ["What is the same-origin policy?", "Browser restricts documents from one origin (scheme + host + port) accessing another origin's DOM, cookies, localStorage. Exception: cross-origin resources can be loaded (script src, img) but not read. CORS relaxes read access for APIs when server allows. Foundation of web security model."],
      ["How does XSS relate to networking and cookies?", "Cross-Site Scripting injects malicious JavaScript stealing cookies or tokens. HttpOnly cookies not readable by script. Content-Security-Policy header restricts script sources. Sanitize output, encode input. Stolen session cookie equals account takeover — security question tied to Set-Cookie flags."],
      ["What is CSRF and how do you prevent it?", "Cross-Site Request Forgery tricks logged-in user's browser to submit unwanted request to bank.com with automatic cookies. Prevent: SameSite=Strict/Lax cookies, CSRF tokens in forms, check Origin/Referer header, require custom header for state-changing APIs (not simple CORS request). Double-submit cookie pattern common."],
      ["How does API rate limiting work at the network edge?", "Track requests per IP, API key, or user in Redis counter or token bucket. Return 429 with Retry-After header. Implemented at API gateway, nginx, or middleware. Protects backend from abuse — Uber and public Google APIs enforce quotas. Distinct from TCP flow control."],
      ["What is a reverse proxy vs forward proxy?", "Forward proxy: client chooses proxy to access internet (corporate firewall). Reverse proxy: client hits proxy thinking it is server — nginx in front of Node.js apps, SSL termination, load balancing, caching. Interview: 'nginx is reverse proxy' is expected answer for MERN deployment."],
      ["What are common port numbers?", "80 HTTP, 443 HTTPS, 22 SSH (Secure Shell), 25 SMTP (Simple Mail Transfer Protocol), 53 DNS, 3306 MySQL, 5432 PostgreSQL, 6379 Redis, 27017 MongoDB. Firewalls and security groups use ports — 'service not reachable' often wrong port or security group."],
      ["What is a socket in networking?", "Socket is endpoint for communication — IP address + port + protocol. Server binds to port and listens; client connects. Berkeley sockets API underlies HTTP libraries. WebSocket name reflects persistent socket abstraction. Distinguish from WebSocket protocol."],
      ["What is SYN flood attack?", "Denial of Service: attacker sends many SYN packets without completing handshake — exhausts server half-open connection table. Mitigation: SYN cookies, firewalls, rate limiting. Shows understanding of TCP state machine beyond textbook handshake."],
      ["What is TIME_WAIT state?", "After connection close, side that initiated close waits ~2×MSL (Maximum Segment Lifetime) to ensure late packets drain. Many short-lived client connections cause many TIME_WAIT sockets — tune or reuse connections via keep-alive. Ops question at scale companies."],
      ["What is mutual TLS (mTLS)?", "Both client and server present certificates — service-to-service auth in microservices (zero trust). Unlike HTTPS where only server cert required. Used internal at Google, Netflix service mesh. Public APIs rarely require client certs."],
      ["Compare gRPC vs REST for microservices.", "gRPC: Protocol Buffers binary, HTTP/2, streaming, strong contracts, faster — internal service calls. REST: JSON human-readable, browser friendly, wide tooling — public APIs. GraphQL for flexible client queries. Pick REST for external MERN API; gRPC for high-performance internal at Amazon scale."],
      ["What is WebRTC in one paragraph?", "WebRTC enables peer-to-peer audio/video and data in browsers without plugins — STUN/TURN servers for Network Address Translation traversal, signaling often over WebSocket. Used in Google Meet, Zoom web. Separate from REST — real-time media path."],
      ["What do ping and traceroute tell you?", "Ping (ICMP Echo): round-trip latency, packet loss — is host reachable? Traceroute: path hops and delay per router — where routing breaks. Basic network debugging before blaming application code. Firewall may block ICMP — mention false negatives."],
      ["IPv4 vs IPv6 — why migrate?", "IPv4: 32-bit addresses (~4 billion), Network Address Translation common. IPv6: 128-bit, vast address space, simplified header, mandatory IPsec support optional in practice. Dual stack common. Cloud load balancers abstract this — know concepts for infrastructure interviews."],
      ["What is subnetting basics?", "IP address split network portion and host portion via subnet mask — 192.168.1.0/24 means 256 addresses, 254 usable hosts. Virtual Private Cloud subnets isolate tiers (public web, private database). Security groups filter by IP and port. AWS interview lite question."],
      ["How would you debug a CORS error step by step?", "Read browser console: blocked by CORS policy. Check request origin and response Access-Control-Allow-Origin — must match exactly or be * without credentials. If preflight, verify OPTIONS returns 204 with Allow-Headers including Authorization. Confirm backend error responses include CORS headers too — error middleware often forgets. Reproduce with curl without CORS (works) vs browser (fails)."],
      ["How would you choose transport for a real-time chat app?", "WebSockets for bidirectional low-latency messages. Fallback long polling for restrictive proxies. REST for history fetch and user profiles. Redis pub/sub or Kafka behind WebSocket servers for horizontal scale. TLS everywhere. Mention sticky sessions or shared pub/sub when multiple WebSocket server instances — Meta system design follow-up."],
      ["What is HSTS?", "HTTP Strict Transport Security header forces browser to use HTTPS only for domain duration max-age — prevents sslstrip downgrade attacks. includeSubDomains extends to all subdomains. Preload list baked into browsers. Set once HTTPS verified working."],
      ["What is the difference between 502 and 504?", "502 Bad Gateway: proxy received invalid response from upstream (crashed app, wrong port). 504 Gateway Timeout: upstream too slow, proxy gave up waiting. Debug: check app logs, upstream health checks, timeout settings on load balancer. On-call engineers see these daily."],
      ["Summarize networking knowledge expected at product company L5 interview.", "Trace full request path DNS→TCP→TLS→HTTP. Design REST APIs with correct verbs, status codes, idempotency. Explain CORS and fix preflight. Choose WebSockets vs polling with trade-offs. Cache with ETag and Cache-Control. Secure with HTTPS, HttpOnly SameSite cookies, CSRF and XSS awareness. Scale with CDN, load balancer, connection pooling. Tie answers to systems you built — Flipkart and Google reward production debugging stories over textbook recitation."],
    ]
  ),
};

await mkdir(OUT, { recursive: true });

for (const [filename, content] of Object.entries(banks)) {
  const path = join(OUT, filename);
  await writeFile(path, content, "utf8");
  const count = (content.match(/^### Q\d+:/gm) || []).length;
  console.log(`${filename}: ${count} questions`);
}

console.log("\nDone. Files written to", OUT);
